// 8-bit Two's Complement Range
#define BITS 8
const int MIN_VAL = -(1 << (BITS - 1)); // -128
const int MAX_VAL = (1 << (BITS - 1)) - 1; // 127

// Detecting Signed Overflow (C/C++ Standard)
// C++20 adds std::numeric::safe_add
int a = 100, b = 50;
if (b > 0 && a > (MAX_VAL - b)) { /* Addition Overflow */ }
if (b < 0 && a < (MIN_VAL - b)) { /* Addition Underflow */ }

// Overflow Behavior (Standard C/C++)
// Signed: Undefined Behavior (Wraps on common systems)
// Unsigned: Guaranteed defined wraparound (Modulo arithmetic)
unsigned char uc = 255;
uc++; // uc == 0 (Defined behavior)
signed char sc = 127;
sc++; // UB (Often wraps to -128)
